import { Injectable, Scope, Inject } from '@nestjs/common';
import { REQUEST } from '@nestjs/core';
import { Request } from 'express';

// ❌ OLD: Injecting REQUEST forces TenantService, UserService, and
// UserController to be re-instantiated on EVERY incoming request.
@Injectable({ scope: Scope.REQUEST })
export class TenantService {
  constructor(@Inject(REQUEST) private request: Request) {}

  getTenantId(): string {
    return this.request.headers['x-tenant-id'] as string;
  }
}

import { Injectable } from '@nestjs/common';
import { AsyncLocalStorage } from 'node:async_hooks';

export const tenantStorage = new AsyncLocalStorage<string>();

// ✅ NEW: TenantService remains a high-performance SINGLETON.
// Request context is accessed through native AsyncLocalStorage with zero re-instantiations.
@Injectable()
export class TenantService {
  getTenantId(): string | undefined {
    return tenantStorage.getStore();
  }
}

